{
 "summary": "Four Karp-style NP-hardness statements for promise problems over bit-string encodings. (1) GapCVP with factor n^{1/400} in ℓ2, for nonsingular integer bases, integer targets and positive rational radius. (2) Binary nearest codeword with factor n^{1/200}. (3) Binary syndrome decoding with factor n^{1/200}. (4) GapCVP in a finite ℓp norm with factor n^{1/(200p)}, for every rational p ≥ 1. In each case every NP language reduces in deterministic polynomial time, with YES inputs sent to YES instances and NO inputs sent to NO instances. The definitions largely match the paper. The main caveats are an asymmetric `0 ≤ blockLength` (vacuous) in the syndrome-decoding YES set and the `disjoint` fields closed by `sorry`. The p-norm corollary is not in the excerpt.",
 "glossary": [
  {"decl": "GapCVP.IsNP", "line": 49, "plain": "L ∈ NP: there are a polynomial certificate-length bound and a poly-time TM verifier V on encoded pairs such that L(x) ⇔ ∃c, |c| ≤ poly(|x|) ∧ V(x,c) = true.", "standard_concept": "NP (verifier definition)", "matches_standard": "yes", "note": ""},
  {"decl": "GapCVP.Comparator.IsNPHardPromise", "line": 147, "plain": "Every NP language has a poly-time map f with L(x) ⇒ f(x) ∈ YES and ¬L(x) ⇒ f(x) ∈ NO.", "standard_concept": "NP-hardness of a promise problem under deterministic Karp reductions", "matches_standard": "yes", "note": ""},
  {"decl": "GapCVP.Comparator.gapCVP400Promise", "line": 135, "plain": "YES: encodings of (n > 0, B ∈ Z^{n×n} with det B ≠ 0, t ∈ Z^n, r ∈ Q>0) with min_v ‖Bv − t‖₂² ≤ r². NO: same well-formedness, with ‖Bv − t‖₂² > (n^{1/400} r)² for all v.", "standard_concept": "GapCVP_{n^{1/400}} as in Theorem 1", "matches_standard": "yes", "note": "The squared comparison is equivalent because r > 0. The disjoint field is proved by sorry, but disjointness holds mathematically since n^{1/400} ≥ 1 and the encoding is injective."},
  {"decl": "GapCVP.Comparator.binaryNearestCodewordPromise", "line": 187, "plain": "YES: (n > 0, G ∈ F2^{n×k}, u, R > 0) with ∃c, wt(u − Gc) ≤ R. NO: ∀c, n^{1/200} R < wt(u − Gc).", "standard_concept": "Gap nearest codeword problem", "matches_standard": "yes", "note": "The code is the column span of an n×k matrix rather than a row span. This is only a convention."},
  {"decl": "GapCVP.Comparator.binarySyndromeDecodingPromise", "line": 244, "plain": "YES: (H ∈ F2^{m×n}, b, R > 0) with ∃x, Hx = b ∧ wt(x) ≤ R, where n = 0 is allowed. NO: n > 0, R > 0, Hx = b is consistent, and every solution has wt(x) > n^{1/200} R.", "standard_concept": "Gap syndrome decoding", "matches_standard": "partly", "note": "The YES set uses the vacuous condition 0 ≤ blockLength while the NO set uses 0 < blockLength. The NO set also requires the system to be consistent."},
  {"decl": "GapCVP.Comparator.finitePGapCVPPromise", "line": 287, "plain": "For rational p ≥ 1. YES: well-formed instance (rational target allowed) with ∃v, ‖t − Bv‖_p ≤ r. NO: ∀v, n^{1/(200p)} r < ‖t − Bv‖_p.", "standard_concept": "GapCVP in ℓp", "matches_standard": "partly", "note": "p is restricted to rationals. The target may be rational, unlike the ℓ2 case. The paper statement is not in the excerpt."}
 ],
 "lean_claims": [
  {"theorem": "gapCVP400IsNPHard", "line": 153, "plain": "GapCVP_{n^{1/400}} (ℓ2, integer target, nonsingular integer basis, r ∈ Q>0) is NP-hard under deterministic poly-time many-one reductions."},
  {"theorem": "binaryNearestCodewordIsNPHard", "line": 212, "plain": "Binary nearest codeword with gap n^{1/200} (n = block length, R > 0) is NP-hard under deterministic poly-time many-one reductions."},
  {"theorem": "binarySyndromeDecodingIsNPHard", "line": 268, "plain": "Binary syndrome decoding with gap n^{1/200} is NP-hard under deterministic poly-time many-one reductions. NO instances must be consistent systems with n > 0."},
  {"theorem": "finitePNormGapCVPIsNPHard", "line": 307, "plain": "For every rational p ≥ 1, GapCVP in ℓp with gap n^{1/(200p)} is NP-hard under deterministic poly-time many-one reductions."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1", "plain": "There is a deterministic poly-time map from 3SAT to (nonsingular B ∈ Z^{n×n}, t ∈ Z^n, r ∈ Q>0) with satisfiable ⇒ dist2 ≤ r and unsatisfiable ⇒ dist2 > n^{1/400} r. Hence GapCVP_{n^{1/400}} is NP-hard."},
  {"ref": "Corollary 15", "plain": "Binary nearest codeword and binary syndrome decoding are NP-hard to approximate within n^{1/200} under deterministic poly-time many-one reductions."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1", "lean_theorem": "gapCVP400IsNPHard", "relation": "equivalent", "why": "Same instance class, gap and reduction notion."},
  {"paper_ref": "Corollary 15 (nearest codeword)", "lean_theorem": "binaryNearestCodewordIsNPHard", "relation": "equivalent", "why": "Standard gap NCP with factor n^{1/200}."},
  {"paper_ref": "Corollary 15 (syndrome decoding)", "lean_theorem": "binarySyndromeDecodingIsNPHard", "relation": "equivalent", "why": "Essentially matches. NO additionally requires consistency (stronger), and YES admits trivial n = 0 instances (negligible)."},
  {"paper_ref": "finite p-norm consequence (Section 7)", "lean_theorem": "finitePNormGapCVPIsNPHard", "relation": "not_formalized", "why": "The precise paper statement is not in the excerpt, so the gap n^{1/(200p)} and the rational-p restriction cannot be checked."}
 ],
 "flags": [
  {"id": "F1", "category": "other", "severity": "low", "decl": "binarySyndromeDecodingPromise", "line": 249, "paper_ref": "Corollary 15", "explanation": "The YES set uses the vacuous `0 ≤ record.blockLength` while the NO set uses `0 < record.blockLength`. So YES includes block-length-0 instances with zero syndrome. This enlarges YES, which slightly eases completeness. It cannot trivialize the reduction, because the map must still separate YES from NO.", "polarity": "lean weaker", "probe_idea": "Show the theorem still holds with `0 < record.blockLength` in YES, i.e., prove a variant using the modified promise."},
  {"id": "F2", "category": "other", "severity": "low", "decl": "binarySyndromeDecodingPromise", "line": 259, "paper_ref": "Corollary 15", "explanation": "NO instances must be consistent (∃x, Hx = b). This shrinks the NO set, so the reduction must output solvable systems.", "polarity": "lean stronger", "probe_idea": null},
  {"id": "F3", "category": "other", "severity": "low", "decl": "gapCVP400Promise / binaryNearestCodewordPromise / binarySyndromeDecodingPromise / finitePGapCVPPromise", "line": 138, "paper_ref": null, "explanation": "The `disjoint` fields are proved by `sorry`, so they are unchecked obligations in the target definitions. They appear true: the gap factor is ≥ 1 for n ≥ 1, and the encodings are prefix-free and hence injective. The theorems do not depend on them.", "polarity": "n/a", "probe_idea": "Prove `Function.Injective encodeInstance` and fill in each disjoint proof."},
  {"id": "F4", "category": "coverage", "severity": "low", "decl": "finitePNormGapCVPIsNPHard", "line": 307, "paper_ref": "Section 7 (finite-norm consequence)", "explanation": "p is restricted to ℚ with p ≥ 1, and rational targets are allowed. The paper's exact p-norm statement and gap are not in the excerpt. If the paper covers all real p ≥ 1, the Lean result is weaker.", "polarity": "unclear", "probe_idea": null}
 ],
